 98	func loadGraphManifest(ctx context.Context, opts Options, repoDir, brainDir string) (*exportManifest, error) {
 99		manifest, err := loadBrainManifest(brainDir)
100		if err != nil {
101			return nil, err
102		}
103		if manifest.Sources == nil {
104			manifest.Sources = &brainSources{}
105		}
106		profile := graphStoreProfile(manifest)
107		d, err := fetchGraphStore(ctx, opts, repoDir, "", profile)
108		if err != nil {
109			return nil, err
110		}
111		manifest.Sources.Semantic = graphStoreSource(d, brainDir)
112		return manifest, nil
113	}
