115	func graphStoreProfile(manifest *exportManifest) string {
116		if manifest != nil && manifest.Sources != nil && manifest.Sources.Semantic != nil && manifest.Sources.Semantic.Profile != "" {
117			return manifest.Sources.Semantic.Profile
118		}
119		return "full"
120	}
