122	// openSemanticReadDB opens the provider's versioned projection. TEMP VIEWs
123	// are connection-local aliases, not a second store. A single connection keeps
124	// those aliases visible throughout the operation. mode=ro protects Graph even
125	// if a future caller accidentally attempts a write.
126	func openSemanticReadDB(handle string) (*sql.DB, error) {
127		if !strings.HasPrefix(handle, graphStoreHandlePrefix) {
128			return sql.Open(sqliteDriverName, sqliteReadOnlyDSN(handle))
129		}
130		raw, err := base64.RawURLEncoding.DecodeString(strings.TrimPrefix(handle, graphStoreHandlePrefix))
131		if err != nil {
132			return nil, err
133		}
134		var d graphStoreDescriptor
135		if err = json.Unmarshal(raw, &d); err != nil {
136			return nil, err
137		}
138		db, err := sql.Open(sqliteDriverName, sqliteReadOnlyDSN(d.Path))
139		if err != nil {
140			return nil, err
141		}
142		db.SetMaxOpenConns(1)
143		fail := func(err error) (*sql.DB, error) { db.Close(); return nil, err }
144		var digest string
145		if err = db.QueryRow("SELECT value FROM meta WHERE key='entry_digest'").Scan(&digest); err != nil {
146			return fail(err)
147		}
148		var actual string
149		if err = json.Unmarshal([]byte(digest), &actual); err != nil || actual != d.EntryDigest {
150			return fail(errors.New("Graph store changed after resolution; retry the operation"))
151		}
152		for _, table := range []string{"symbols", "relations", "files", "reverse_relations", "symbol_fts"} {
153			if _, err = db.Exec("CREATE TEMP VIEW " + table + " AS SELECT * FROM main.brain_" + table + "_v1"); err != nil {
154				return fail(err)
155			}
156		}
157		if err = loadGraphTraceTable(db, d.BrainDir); err != nil {
158			return fail(err)
159		}
160		return db, nil
161	}
