163	func runGraphOwnedIndex(ctx context.Context, cmd *cobra.Command, opts Options, indexOpts semanticIndexOptions, target string) error {
164		if ctx == nil {
165			ctx = context.Background()
166		}
167		if indexOpts.worktree {
168			return errors.New("Graph owns the committed-tree index; use entire graph query without --head to inspect uncommitted code")
169		}
170		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
171		if err != nil {
172			return err
173		}
174		if !local {
175			return fmt.Errorf("index requires a local repository: %s", target)
176		}
177		if err = enforceIndexContainment(indexOpts.containRoot, repoDir); err != nil {
178			return err
179		}
180		if _, err := gitScalar(ctx, opts.Runner, repoDir, "rev-parse", "HEAD"); err != nil {
181			return nameDegenerateRepoFailure(ctx, opts.Runner, repoDir, fmt.Errorf("resolve HEAD for Graph index: %w", err))
182		}
183		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
184		if err != nil {
185			return err
186		}
187		if indexOpts.outputExplicit {
188			storage.BrainDir, err = filepath.Abs(indexOpts.outputDir)
189			if err != nil {
190				return err
191			}
192		}
193		// Retire the duplicate even on installations without Graph. Authored
194		// observations are durable; code indexes are reproducible provider data.
195		if err := migrateBrainGraphStorage(storage.BrainDir, storage.Key); err != nil {
196			return err
197		}
198		binary := indexOpts.graphBinary
199		if binary == "" {
200			binary = indexOpts.semBinary
201		}
202		if binary == "" {
203			binary = "entire"
204		}
205		if indexOpts.skipGraph || indexOpts.skipSem {
206			return semanticProviderAbsentError{err: errors.New("Graph was explicitly disabled")}
207		}
208		doctor, warnings := runSemanticDoctor(ctx, opts.Runner, repoDir, binary)
209		if !doctor.NoEgress {
210			return semanticDoctorFailureError(binary, warnings)
211		}
212		profile := indexOpts.profile
213		if profile == "" {
214			profile = "full"
215		}
216		args := []string{"graph", "index", "--repo", repoDir, "--head", "--profile", profile, "--format", "json"}
217		if indexOpts.force {
218			args = append(args, "--force")
219		}
220		ignores, err := semanticProviderIgnoreFiles(repoDir)
221		if err != nil {
222			return err
223		}
224		for _, ignore := range ignores {
225			args = append(args, "--ignore-file", ignore)
226		}
227		runner, ok := opts.Runner.(EnvironmentCommandRunner)
228		if !ok {
229			return errors.New("Graph indexing requires a runner supporting per-command environment")
230		}
231		if _, probeErr := fetchGraphStore(ctx, opts, repoDir, binary, profile); errors.Is(probeErr, errGraphStoreUnsupported) {
232			return probeErr
233		}
234		timeout := indexOpts.timeout
235		if timeout <= 0 {
236			timeout = semanticSnapshotTimeout
237		}
238		ctx, cancel := context.WithTimeout(ctx, timeout)
239		defer cancel()
240		indexOpts.reportPhase("building Graph-owned store")
241		stdout, stderr, err := runner.RunWithEnv(ctx, repoDir, map[string]string{"ENTIRE_GRAPH_SEARCH_STORE": "1"}, binary, args...)
242		if err != nil {
243			return fmt.Errorf("Graph index: %w: %s", err, firstLine(strings.TrimSpace(string(stderr))))
244		}
245		d, err := fetchGraphStore(ctx, opts, repoDir, binary, profile)
246		if err != nil {
247			return err
248		}
249		unlock, err := acquireSemanticIndexLock(storage.BrainDir)
250		if err != nil {
251			return err
252		}
253		defer unlock()
254		// Preserve authored traces before removing any legacy graph artifacts.
255		if err = migrateLegacyGraphTraces(storage.BrainDir); err != nil {
256			return err
257		}
258		source := graphStoreSource(d, storage.BrainDir)
259		source.StorePath = ""
260		source.GeneratedAt = opts.Now().UTC()
261		source.Profile = profile
262		source.GraphRepoRoot = repoDir
263		if err = writeBrainSemanticSource(storage.BrainDir, storage.Key, source); err != nil {
264			return err
265		}
266		if err = removeLegacyGraphArtifacts(storage.BrainDir); err != nil {
267			return err
268		}
269	
270		var indexed struct {
271			CacheHit bool `json:"index_cache_hit"`
272		}
273		_ = json.Unmarshal(stdout, &indexed)
274		label := "Graph-owned index"
275		if indexed.CacheHit {
276			label += " already current"
277		}
278		fmt.Fprintf(cmd.OutOrStdout(), "%s: %d files, %d symbols, %d relations\n", label, d.Files, d.Symbols, d.Relations)
279		return nil
280	}
281	
282	func removeLegacyGraphArtifacts(brainDir string) error {
283		for _, rel := range []string{"semantic/generations", "semantic/snapshots"} {
284			if err := rejectExistingSymlinkPathComponents(brainDir, rel); err != nil {
285				return err
286			}
287			if err := os.RemoveAll(filepath.Join(brainDir, rel)); err != nil {
288				return err
289			}
290		}
291		return nil
292	}
293	
294	func migrateBrainGraphStorage(brainDir, repoKey string) error {
295		unlock, err := acquireSemanticIndexLock(brainDir)
296		if err != nil {
297			return err
298		}
299		defer unlock()
300		manifest, err := loadBrainManifest(brainDir)
301		if err != nil {
302			return err
303		}
304		if manifest.Sources == nil || manifest.Sources.Semantic == nil {
305			return nil
306		}
307		if err = migrateLegacyGraphTraces(brainDir); err != nil {
308			return err
309		}
310		if manifest.Sources.Semantic.StoreOwner != "graph" {
311			source := &semanticSourceManifest{StoreOwner: "graph", Provider: "entire-graph", Profile: manifest.Sources.Semantic.Profile}
312			if err = writeBrainSemanticSource(brainDir, repoKey, source); err != nil {
313				return err
314			}
315		}
316		return removeLegacyGraphArtifacts(brainDir)
317	}

