	}
	if !info.IsDir() {
		return nil, fmt.Errorf("brain layer must be a directory: %s", layer.dir)
	}
	var paths []string
	err = filepath.WalkDir(layerRoot, func(path string, d os.DirEntry, walkErr error) error {
		if walkErr != nil {
