	}
	var res struct {
		Tools []Tool `json:"tools"`
	}
	if err := json.Unmarshal(raw, &res); err != nil {
		return nil, fmt.Errorf("hostedbrain: decode tools/list: %w", err)
	}
	return res.Tools, nil
}
